item.command:
/bin/bash -lc "python - <<'PY'
from pathlib import Path
from openpyxl import load_workbook
for p in [Path('inputs/230214_Schenz_et_al_2022_CHIP_Genes.xlsx'), Path('inputs/230215_Trio_Status.xlsx'), *list(sorted(Path('inputs/CHIP_DP10_GQ20_PASS').glob('*.xlsx')))[:3]]:
    wb=load_workbook(p, read_only=True, data_only=True)
    print(p, wb.sheetnames)
    for ws in wb.worksheets:
        print(' ',ws.title,ws.max_row,ws.max_column)
        for row in ws.iter_rows(min_row=1,max_row=min(5,ws.max_row),values_only=True): print('   ',row)
PY"

