item.command:
/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['xlsx2csv','pandas']:
 url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true'
 try:
  with urllib.request.urlopen(url, timeout=30) as h: d=json.load(h)
  print(repo, [t['name'] for t in d.get('tags',[])[:8]])
 except Exception as e: print(repo, type(e).__name__)
PY"

/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['xlsx2csv','pandas']:
 url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true'
 try:
  with urllib.request.urlopen(url, timeout=30) as h: d=json.load(h)
  print(repo, [t['name'] for t in d.get('tags',[])[:8]])
 except Exception as e: print(repo, type(e).__name__)
PY"

